import { test, expect } from '@playwright/test';

test.describe('Comment on a record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display the comment input field', async ({ page }) => {
    const commentInput = page.getByLabel('Comment');
    await expect(commentInput).toBeVisible();
  });

  test('should allow a user to submit a comment', async ({ page }) => {
    const commentInput = page.getByLabel('Comment');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await commentInput.fill('This is a test comment.');
    await submitButton.click();

    const successMessage = page.getByText('Comment submitted successfully!');
    await expect(successMessage).toBeVisible();
  });
});
